#include "recheck_dialog.hpp"
#include <QLabel>
#include <QProgressBar>
#include <QPushButton>
#include <QPointer>
#include <QVBoxLayout>
#include <algorithm>
namespace biglybtc::ui {
RecheckDialog::RecheckDialog(QWidget* parent):QDialog(parent){setObjectName("force-recheck-dialog");setWindowTitle(tr("Force Recheck"));auto* layout=new QVBoxLayout(this);scope_=new QLabel(tr("The worker retires transfers, checks supported pieces without repairing or deleting payload, and saves the checked resume map. Previously active torrents return to their queue after checking and may download missing or corrupt pieces. Stopped or paused torrents keep that intent. Cancelling retires this operation; saved startup intent can still apply on a later reopen."),this);scope_->setTextFormat(Qt::PlainText);scope_->setWordWrap(true);layout->addWidget(scope_);status_=new QLabel(this);status_->setObjectName("recheck-status");status_->setTextFormat(Qt::PlainText);status_->setWordWrap(true);layout->addWidget(status_);progress_=new QProgressBar(this);progress_->setObjectName("recheck-progress");progress_->setRange(0,1000);layout->addWidget(progress_);counts_=new QLabel(this);counts_->setObjectName("recheck-counts");counts_->setTextFormat(Qt::PlainText);counts_->setWordWrap(true);layout->addWidget(counts_);cancel_=new QPushButton(tr("Cancel Recheck"),this);cancel_->setObjectName("recheck-cancel");layout->addWidget(cancel_);connect(cancel_,&QPushButton::clicked,this,&RecheckDialog::reject);resize(600,250);}
RecheckDialog::~RecheckDialog(){stop(false);}
void RecheckDialog::stop(bool notify){if(!request_||terminal_){return;}const auto key=request_->key;const auto receiver=request_->receiver;request_.reset();QPointer<RecheckDialog> alive(this);if(receiver){receiver->request_stop();}if(alive&&notify){emit cancelled(key);}}
bool RecheckDialog::begin(RecheckRequest request){if(!request.key.session||!request.key.request||request.targets.empty()||!request.receiver||request.receiver->stop_requested()){return false;}const auto revision=++revision_;QPointer<RecheckDialog> alive(this);stop(true);if(!alive||revision_!=revision){return false;}request_=std::move(request);sequence_=0;terminal_=false;status_->setText(tr("Waiting for the current worker to accept the actual selection…"));if(!alive||revision_!=revision){return false;}progress_->setValue(0);if(!alive||revision_!=revision){return false;}counts_->clear();if(!alive||revision_!=revision){return false;}cancel_->setText(tr("Cancel Recheck"));return alive&&revision_==revision;}
void RecheckDialog::present(RecheckPresentation packet){if(!packet||!request_||packet->key!=request_->key||packet->sequence<=sequence_){return;}sequence_=packet->sequence;terminal_=packet->terminal;const auto revision=++revision_;QPointer<RecheckDialog> alive(this);status_->setText(packet->message.left(4096));if(!alive||revision_!=revision){return;}const auto maximum=std::max(packet->totalBytes,packet->scannedBytes);const auto value=maximum?static_cast<int>(std::min<long double>(1000.0L,1000.0L*packet->scannedBytes/maximum)):0;progress_->setValue(value);if(!alive||revision_!=revision){return;}counts_->setText(tr("Torrent %1 of %2 · %3 / %4 bytes\nVerified pieces: %5 · bad: %6 · missing: %7 · unverified: %8\nResume map: %9").arg(packet->targetIndex).arg(packet->totalTargets).arg(packet->scannedBytes).arg(packet->totalBytes).arg(packet->goodPieces).arg(packet->badPieces).arg(packet->missingPieces).arg(packet->unknownPieces).arg(packet->saveUncertain?tr("save needs review"):packet->pieceMapSaved?tr("saved"):tr("not saved")));if(!alive||revision_!=revision){return;}cancel_->setText(terminal_?tr("Close"):tr("Cancel Recheck"));}
void RecheckDialog::refused(RecheckKey key){if(!request_||request_->key!=key){return;}QPointer<RecheckDialog> alive(this);stop(false);if(!alive){return;}terminal_=true;++revision_;status_->setText(tr("Recheck was not accepted. Refresh the actual library and try again."));if(alive){cancel_->setText(tr("Close"));}}
void RecheckDialog::invalidate(){const auto revision=++revision_;QPointer<RecheckDialog> alive(this);stop(true);if(!alive||revision_!=revision){return;}request_.reset();terminal_=true;QDialog::reject();}
void RecheckDialog::reject(){const auto revision=++revision_;QPointer<RecheckDialog> alive(this);stop(true);if(alive&&revision_==revision){QDialog::reject();}}
}
